14	    public static String formatMatchIndexes(List<Integer> matchIndexes) {
15	        Objects.requireNonNull(matchIndexes, "matchIndexes must not be null");
16	
17	        if (matchIndexes.isEmpty()) {
18	            return "";
19	        }
20	
21	        StringBuilder formattedMatches = new StringBuilder();
22	        for (int index = 0; index < matchIndexes.size(); index++) {
23	            if (index > 0) {
24	                formattedMatches.append(' ');
